<?php
if(!defined('ABSPATH'))exit;
add_action('init',function(){register_post_type('dgs_gallery',array('labels'=>array('name'=>'گالری تصاویر مدرسه','singular_name'=>'تصویر مدرسه','add_new'=>'افزودن تصویر جدید','add_new_item'=>'افزودن تصویر جدید','edit_item'=>'ویرایش تصویر','all_items'=>'همه تصاویر','featured_image'=>'تصویر گالری','set_featured_image'=>'انتخاب / بارگذاری تصویر','remove_featured_image'=>'حذف تصویر انتخابی'),'public'=>false,'show_ui'=>true,'show_in_rest'=>false,'show_in_menu'=>'dgs-setup','supports'=>array('title','excerpt','thumbnail','page-attributes'),'capabilities'=>array('create_posts'=>'manage_options','edit_posts'=>'manage_options','edit_others_posts'=>'manage_options','publish_posts'=>'manage_options','delete_posts'=>'manage_options','delete_others_posts'=>'manage_options','read_private_posts'=>'manage_options'),'map_meta_cap'=>true));},9);
function dgs_gallery_url(){$p=get_option('dgs_pages',array());return !empty($p['gallery'])&&get_post_status($p['gallery'])==='publish'?get_permalink($p['gallery']):add_query_arg('dgs_gallery','1',home_url('/'));}
function dgs_gallery_ensure_page(){
 $p=get_option('dgs_pages',array());if(!empty($p['gallery'])&&get_post_type($p['gallery'])==='page'&&get_post_status($p['gallery'])!=='trash')return (int)$p['gallery'];$found=get_posts(array('post_type'=>'page','post_status'=>array('publish','draft','private'),'numberposts'=>1,'meta_key'=>'_dgs_page_key','meta_value'=>'gallery'));$id=$found?$found[0]->ID:wp_insert_post(wp_slash(array('post_type'=>'page','post_status'=>'publish','post_title'=>'گالری تصاویر مدرسه','post_name'=>'school-gallery','post_content'=>'[daneshgaran_gallery]','meta_input'=>array('_dgs_page_key'=>'gallery'))),true);if(is_wp_error($id)||!$id)return new WP_Error('gallery_page','صفحه گالری ساخته نشد.');$p['gallery']=(int)$id;update_option('dgs_pages',$p);return (int)$id;
}
function dgs_gallery_active(){$p=get_option('dgs_pages',array());return (!empty($p['gallery'])&&is_page((int)$p['gallery']))||dgs_catalog_get('dgs_gallery')==='1';}
function dgs_gallery_query($limit=12,$page=1){return new WP_Query(array('post_type'=>'dgs_gallery','post_status'=>'publish','posts_per_page'=>max(1,min(30,(int)$limit)),'paged'=>max(1,(int)$page),'meta_query'=>array(array('key'=>'_thumbnail_id','compare'=>'EXISTS')),'orderby'=>array('menu_order'=>'ASC','date'=>'DESC','ID'=>'DESC')));}
function dgs_gallery_card($p,$compact=false){$image=get_post_thumbnail_id($p->ID);if(!dgs_showcase_image_valid($image))return '';$src=wp_get_attachment_image_url($image,'large');$alt=get_post_meta($image,'_wp_attachment_image_alt',true)?:$p->post_title;return '<figure class="dgg-item"><a class="dgg-open" href="'.esc_url($src).'" data-dgg-title="'.esc_attr($p->post_title).'">'.wp_get_attachment_image($image,$compact?'medium':'medium_large',false,array('alt'=>$alt,'loading'=>'lazy','decoding'=>'async')).'<span>'.dgs_showcase_icon('image').'</span></a><figcaption><strong>'.esc_html($p->post_title).'</strong>'.(!$compact&&$p->post_excerpt?'<p>'.esc_html(wp_trim_words($p->post_excerpt,30)).'</p>':'').'</figcaption></figure>';}
function dgs_gallery_preview($limit=8,$settings=array()){
 $q=dgs_gallery_query($limit);$title=is_string($settings['gallery_title']??null)?$settings['gallery_title']:'گالری تصاویر مدرسه';$description=is_string($settings['gallery_description']??null)?$settings['gallery_description']:'نگاهی به فضای آموزشی، امکانات و فعالیت‌های فرهنگی و علمی مدرسه';$label=is_string($settings['gallery_link_label']??null)?$settings['gallery_link_label']:'مشاهده گالری کامل';$out='<section class="dgg-preview" id="'.esc_attr(wp_unique_id('school-gallery-')).'"><div class="dgg-preview-intro"><h2>'.dgs_showcase_icon('image').esc_html($title).'</h2><p>'.esc_html($description).'</p><a class="dsh-soft-button" href="'.esc_url(dgs_gallery_url()).'">'.dgs_showcase_icon('image').esc_html($label).'</a></div><div class="dgg-preview-body">';if($q->posts){$out.='<div class="dgg-controls"><button type="button" data-dgg-scroll="prev" aria-label="تصاویر قبلی">‹</button><button type="button" data-dgg-scroll="next" aria-label="تصاویر بعدی">›</button></div><div class="dgg-track">';foreach($q->posts as $p)$out.=dgs_gallery_card($p,true);$out.='</div>';}else $out.=dgs_empty('هنوز تصویری در گالری مدرسه منتشر نشده است.');return $out.'</div></section>';
}
function dgs_gallery_page(){
 $page=max(1,min(10000,absint(dgs_catalog_get('gallery_page','1'))));$q=dgs_gallery_query(12,$page);$out='<div class="dgg-page">'.'<header class="dc-heading"><h1>'.dgs_showcase_icon('image').'گالری تصاویر مدرسه</h1><p>تصاویر فضای مدرسه و فعالیت‌های آموزشی، فرهنگی و علمی</p></header>'.'<div class="dgg-grid">';foreach($q->posts as $p)$out.=dgs_gallery_card($p);if(!$q->posts)$out.=dgs_empty('تصویری در گالری منتشر نشده است.');$out.='</div>'.dgs_catalog_pagination($page,(int)$q->max_num_pages,'gallery_page',dgs_gallery_url()).'<a class="dsh-soft-button" href="'.esc_url(home_url('/')).'">بازگشت به صفحه اصلی</a></div>';return $out;
}
add_shortcode('daneshgaran_gallery','dgs_gallery_page');
add_filter('template_include',function($template){return get_template()==='daneshgaran'&&dgs_gallery_active()?DGS_PATH.'includes/gallery-template.php':$template;},110);
add_filter('wp_insert_post_data',function($data,$postarr){if(($data['post_type']??'')!=='dgs_gallery'||($data['post_status']??'')!=='publish')return $data;$id=absint($postarr['ID']??0);$thumb=isset($postarr['meta_input']['_thumbnail_id'])?absint($postarr['meta_input']['_thumbnail_id']):(isset($_POST['_thumbnail_id'])&&is_scalar($_POST['_thumbnail_id'])?max(0,(int)$_POST['_thumbnail_id']):get_post_thumbnail_id($id));if(!dgs_showcase_image_valid($thumb)){$data['post_status']='draft';set_transient('dgs_gallery_image_notice_'.get_current_user_id(),1,60);}return $data;},20,2);
add_action('admin_notices',function(){if(get_transient('dgs_gallery_image_notice_'.get_current_user_id())){delete_transient('dgs_gallery_image_notice_'.get_current_user_id());echo '<div class="notice notice-warning"><p>برای انتشار تصویر گالری، ابتدا یک تصویر JPG/PNG/WebP از بخش «تصویر گالری» انتخاب کنید؛ نوشته فعلاً پیش‌نویس ذخیره شد.</p></div>';}});
function dgs_gallery_invalidate($id=0){$p=get_option('dgs_pages',array());if(!empty($p['gallery']))dgs_catalog_invalidate($p['gallery']);if($id)dgs_catalog_invalidate($id);}
add_action('save_post_dgs_gallery',function($id){if(!wp_is_post_revision($id))dgs_gallery_invalidate($id);},100);
add_action('before_delete_post',function($id){if(get_post_type($id)==='dgs_gallery')dgs_gallery_invalidate($id);});
add_action('trashed_post',function($id){if(get_post_type($id)==='dgs_gallery')dgs_gallery_invalidate($id);});
add_action('updated_post_meta',function($meta_id,$id,$key){if($key==='_thumbnail_id'&&get_post_type($id)==='dgs_gallery')dgs_gallery_invalidate($id);},10,3);
function dgs_gallery_import_existing(){
 if(get_option('dgs_gallery_imported_019'))return;$items=array();for($i=0;$i<4;$i++){$image=absint(dgs_showcase_setting('gallery_image_'.$i));if(dgs_showcase_image_valid($image))$items[$image]=dgs_showcase_setting('gallery_label_'.$i);}
 foreach(dgs_elementor_targets() as $id){$data=json_decode(get_post_meta($id,'_elementor_data',true),true);$walk=function($nodes)use(&$walk,&$items){foreach((array)$nodes as $node){if(($node['widgetType']??'')==='dgs_picture'&&preg_match('/^gallery[0-3]$/D',$node['settings']['reference']??'')){$image=absint($node['settings']['image']['id']??0);if(dgs_showcase_image_valid($image))$items[$image]=$node['settings']['caption']??get_the_title($image);}if(!empty($node['elements']))$walk($node['elements']);}};$walk($data);}
 foreach($items as $image=>$title){$found=get_posts(array('post_type'=>'dgs_gallery','post_status'=>array('publish','draft'),'numberposts'=>1,'meta_key'=>'_thumbnail_id','meta_value'=>$image));if($found)continue;$id=wp_insert_post(wp_slash(array('post_type'=>'dgs_gallery','post_status'=>'publish','post_title'=>$title?:get_the_title($image),'meta_input'=>array('_thumbnail_id'=>$image,'_dgs_imported_gallery'=>'1'))),true);if(is_wp_error($id)||!$id)return;}update_option('dgs_gallery_imported_019','1',false);
}
add_action('admin_init',function(){if(!current_user_can('manage_options'))return;$page=dgs_gallery_ensure_page();if(!is_wp_error($page))dgs_gallery_import_existing();if(class_exists('\\Elementor\\Plugin'))dgs_gallery_upgrade_elementor();},40);
function dgs_gallery_register_assets(){if(wp_style_is('dgs-gallery','registered'))return;wp_register_style('dgs-gallery',false,array(),DGS_VERSION);wp_add_inline_style('dgs-gallery',file_get_contents(DGS_PATH.'assets/gallery.css'));wp_register_script('dgs-gallery',false,array(),DGS_VERSION,true);wp_add_inline_script('dgs-gallery',file_get_contents(DGS_PATH.'assets/gallery.js'));}
add_action('wp_enqueue_scripts','dgs_gallery_register_assets',5);
add_action('wp_enqueue_scripts',function(){if(dgs_showcase_active()||dgs_gallery_active()){dgs_gallery_register_assets();wp_enqueue_style('dgs-gallery');wp_enqueue_script('dgs-gallery');}});
add_action('wp_footer',function(){if(!dgs_showcase_active()&&!dgs_gallery_active()&&!wp_script_is('dgs-gallery','enqueued'))return;echo '<dialog id="dgg-lightbox" class="dgg-lightbox" aria-label="نمایش تصویر گالری"><button type="button" data-dgg-close aria-label="بستن تصویر">×</button><img alt=""><p></p><div><button type="button" data-dgg-step="-1">تصویر قبلی</button><button type="button" data-dgg-step="1">تصویر بعدی</button></div></dialog>';});
